import glob, os
import numpy as np, pandas as pd, tifffile
from cellpose import models
from skimage.measure import regionprops

model = models.CellposeModel(model_type='nuclei', gpu=False)
ann_files = sorted(glob.glob('/task/input/annotations/*.tsv'))
annotations = {os.path.basename(af).replace('.tsv', ''): pd.read_csv(af, sep='\t') for af in ann_files}

# Cache masks for the 8 wells
masks_dict = {}
for w in annotations:
    img = tifffile.imread(f'/task/input/images/{w}_ch1.tif')
    masks, _, _ = model.eval(img, diameter=11.0, channels=[0,0], cellprob_threshold=-1.0, flow_threshold=0.7)
    masks_dict[w] = masks

for area_thresh in [30, 35, 40, 45, 50, 60]:
    for minor_thresh in [5.0, 5.5, 6.0, 6.5]:
        all_pass = True
        rows = []
        for w, df in annotations.items():
            props = regionprops(masks_dict[w])
            counted = 0
            for p in props:
                minr, minc, maxr, maxc = p.bbox
                if maxr >= 320 or maxc >= 320:
                    continue
                touches_top_left = (minr == 0 or minc == 0)
                if touches_top_left:
                    if p.area < 25:
                        continue
                else:
                    if p.area < area_thresh or p.minor_axis_length < minor_thresh:
                        continue
                counted += 1
            n_manual = len(df)
            tol = max(3.0, 0.10 * n_manual)
            diff = abs(counted - n_manual)
            passed = diff <= tol
            if not passed: all_pass = False
            rows.append((w, n_manual, counted, diff, tol, passed))
        if all_pass:
            print(f"ALL PASS! area_thresh={area_thresh}, minor_thresh={minor_thresh}")
            for r in rows:
                print(f"  {r[0]}: manual={r[1]:3d}, pipeline={r[2]:3d}, diff={r[3]:2d}, tol={r[4]:.1f}, pass={r[5]}")
            exit(0)
EOF
